exercises.starter:
pub fn widest(raw: &str) -> String {
    let best = raw
        .split(',')
        .map(|f| f.trim().parse().unwrap())
        .max()
        .unwrap();
    format!("{best}")
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn finds_the_largest() {
        assert_eq!(widest("1024, 65536, 300"), "65536");
    }
    #[test]
    fn handles_one_field() {
        assert_eq!(widest("42"), "42");
    }
}

exercises.solution:
pub fn widest(raw: &str) -> String {
    let best = raw
        .split(',')
        .map(|f| f.trim().parse::<u32>().unwrap())
        .max()
        .unwrap();
    format!("{best}")
}
